using System;using System.IO;using System.Linq;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class JointPreviewTests {
  public static int Cache(string file){try{var d=RobotDocument.Parse(File.ReadAllText(file));foreach(var j in d.Joints)if(j.GeneratedBody.Fingerprint!=ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator))throw new Exception("cache compatibility: "+j.Name);var old=RobotDocument.EnclosedExample();old.Joints[0].EndZ=180;old.Joints[3].EndZ=110;old.Joints[5].EndX=85;if(!RobotDesignerForm.UpgradeReferenceSpacing(old)||old.Joints[3].EndZ!=160)throw new Exception("old reference update");old.Joints[1].EndX=1;old.Joints[3].EndZ=110;if(RobotDesignerForm.UpgradeReferenceSpacing(old)||old.Joints[3].EndZ!=110)throw new Exception("custom geometry must remain untouched");File.WriteAllText(Path.Combine(Path.GetDirectoryName(file),"cache-results.txt"),"PASS 6 native cache keys preserved; old reference update; custom skeleton unchanged.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(Path.GetDirectoryName(file),"cache-error.txt"),ex.ToString());return 1;}}
  public static int Run(string folder){try{var result=CADDocument.Serializer().Deserialize<CADKernelResult>(File.ReadAllText(Path.Combine(folder,"result.json")));var assembly=new CadAssembly();foreach(var data in result.Procedural.Parts){if(data.Role=="hardware"||data.Role=="insert")continue;var body=result.Bodies.Single(b=>b.Id==data.Id);body.ReadMesh();data.Preview=CADMeshCodec.Encode(body.Display);data.Volume=body.Volume;data.Center=body.Center;data.Bounds=body.Bounds;assembly.Parts.Add(ProceduralBodySpec.Part(data.Id,data));}using(var scene=new WpfScene()){scene.SetResult(new Result{P=new Parameters{Kind=9},Model=assembly},false);scene.Camera.Yaw=.9;scene.Camera.Pitch=.3;scene.Fit();scene.SavePng(Path.Combine(folder,"review.png"),1200,950);scene.Camera.Yaw=Math.PI/2;scene.Camera.Pitch=0;scene.Camera.Update();scene.SavePng(Path.Combine(folder,"side.png"),1200,950);}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"preview-error.txt"),ex.ToString());return 1;}}
 }
}
